#include <print>
#include <utility>
#include <vector>

void bubble_all(std::vector<int>& v) {
    for (size_t i = 0; i + 1 < v.size(); i++) {
        for (size_t j = 0; j + 1 < v.size() - i; j++) {
            if (v[j] > v[j + 1]) std::swap(v[j], v[j + 1]);
        }
    }
}

int main() {
    std::vector<int> e = {};
    std::vector<int> one = {42};
    std::vector<int> v = {5, 2, 8, 1};

    bubble_all(e);
    bubble_all(one);
    bubble_all(v);

    std::println("空 {} 单 {} 四个 {}", e, one, v);

    // 空盒子时 1 < 0 不成立，一轮都不进；0 减 1 是无符号下溢，翻成极大的数，条件看着还成立就冲进盒子外面了
    return 0;
}

